WITH metrics AS (SELECT id, store_name, city, LAG(sqft) OVER w_hist AS prev_sqft, ROW_NUMBER() OVER w_hist AS seq_no FROM stores WINDOW w_hist AS (PARTITION BY city ORDER BY opened_date ASC, id ASC)), with_windows AS (SELECT id, store_name, city, SUM(seq_no) OVER (PARTITION BY city) AS city_sum_seq_no, ROW_NUMBER() OVER (ORDER BY seq_no DESC, id ASC) AS event_seq, ROW_NUMBER() OVER (PARTITION BY city ORDER BY seq_no DESC, id ASC) AS row_seq, RANK() OVER (PARTITION BY city ORDER BY seq_no DESC NULLS LAST) AS seq_no_rank, ROUND(prev_sqft / SUM(prev_sqft) OVER (PARTITION BY city), 4) AS prev_sqft_share FROM metrics WHERE seq_no < 3), deduped AS (SELECT * FROM with_windows QUALIFY ROW_NUMBER() OVER (PARTITION BY city ORDER BY prev_sqft_share DESC, id ASC) = 1), with_windows_stores AS (SELECT *, MAX(event_seq) OVER (PARTITION BY city) AS city_max_event_seq, AVG(seq_no_rank) OVER (ORDER BY city_sum_seq_no ASC, id ASC ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING) AS seq_no_rank_avg_3_prior FROM deduped) SELECT id, store_name, city, city_sum_seq_no, event_seq, row_seq, prev_sqft_share, seq_no_rank_avg_3_prior, CASE WHEN city RLIKE '^(New York|Singapore)$' THEN 'PRIORITY' WHEN city RLIKE '^(Bangkok|Chiang Mai)$' THEN 'GROUP_A' ELSE 'OTHER_ZONE' END AS city_zone FROM with_windows_stores ORDER BY city ASC;
